package com.enterprise.mm.erp.warehouse;

import com.enterprise.mm.common.*;
import com.enterprise.mm.error.*;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.node.*;
import java.math.BigDecimal;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.sql.Date;
import java.sql.Timestamp;
import java.time.*;
import java.util.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/** Native source facts only; intentionally has no operational stock/costing dependencies. */
@Service
public class WarehouseMirrorService {
    private final JdbcTemplate jdbc; private final ObjectMapper mapper; private final WarehouseMirrorSettings settings;
    public WarehouseMirrorService(JdbcTemplate jdbc,ObjectMapper mapper,WarehouseMirrorSettings settings){this.jdbc=jdbc;this.mapper=mapper;this.settings=settings;}
    private String tenant(){String value=TenantContext.currentTenant();if(value==null||value.isBlank())throw new BadRequestException("Tenant scope required");return value;}
    private UUID company(){UUID value=CompanyContext.currentCompany();if(value==null)throw new BadRequestException("Company scope required");return value;}
    private void lock(){jdbc.queryForObject("select pg_advisory_xact_lock(hashtextextended(cast(? as text)||':'||cast(? as text)||':warehouse-v2',0))",Object.class,tenant(),company());}
    public Map<String,Object> config(){return settings.config();}

    @Transactional
    public Map<String,Object> receive(JsonNode payload){settings.requireEnabled();lock();return apply(payload);}
    private Map<String,Object> apply(JsonNode n){
        validate(n);String hash=hash(n);UUID event=uuid(n,"eventId");
        var eventRows=jdbc.queryForList("select document_head_id,revision,payload_hash from one_c_warehouse_revisions where tenant_id=? and company_id=? and event_id=?",tenant(),company(),event);
        if(!eventRows.isEmpty())return replay(eventRows.getFirst(),hash);
        String source=text(n,"sourceInstanceId",160),org=text(n,"organizationId",160),type=text(n,"documentType",240),nativeId=text(n,"documentId",160);long revision=n.path("revision").asLong();
        var heads=jdbc.queryForList("select * from one_c_warehouse_documents where tenant_id=? and company_id=? and source_instance_id=? and organization_id=? and document_type=? and document_id=? for update",tenant(),company(),source,org,type,nativeId);
        UUID id=heads.isEmpty()?UUID.randomUUID():(UUID)heads.getFirst().get("id");
        var old=jdbc.queryForList("select document_head_id,revision,payload_hash from one_c_warehouse_revisions where document_head_id=? and revision=?",id,revision);
        if(!old.isEmpty())return replay(old.getFirst(),hash);
        boolean current=heads.isEmpty()||revision>((Number)heads.getFirst().get("revision")).longValue();
        if(heads.isEmpty())jdbc.update("insert into one_c_warehouse_documents(id,tenant_id,company_id,source_instance_id,organization_id,document_type,document_id,revision,state,document_date,document_number,origin,correlation_id,row_count,coverage) values(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)",id,tenant(),company(),source,org,type,nativeId,revision,n.path("state").asText(),Date.valueOf(n.path("documentDate").asText()),optional(n,"documentNumber"),n.path("origin").asText("ONE_C"),optional(n,"correlationId"),n.path("rows").size(),"MAPPING_REQUIRED");
        jdbc.update("insert into one_c_warehouse_revisions(id,document_head_id,tenant_id,company_id,event_id,revision,state,payload_hash,payload) values(?,?,?,?,?,?,?,?,cast(? as jsonb))",UUID.randomUUID(),id,tenant(),company(),event,revision,n.path("state").asText(),hash,n.toString());
        if(current){
            jdbc.update("delete from one_c_warehouse_current_rows where document_head_id=?",id);boolean unmapped=false;
            for(JsonNode r:n.path("rows")){
                UUID material=resolve("MATERIAL",nativeId(r,"materialId")),warehouse=resolve("WAREHOUSE",nativeId(r,"warehouseId"));unmapped|=material==null||warehouse==null;
                jdbc.update("insert into one_c_warehouse_current_rows(document_head_id,row_key,period,side,account_id,account_code,material_id,material_name,warehouse_id,warehouse_name,quantity,amount,currency,analytics,mapped_material_id,mapped_warehouse_id) values(?,?,?,?,?,?,?,?,?,?,?,?,?,cast(? as jsonb),?,?)",id,r.path("rowKey").asText(),Timestamp.valueOf(LocalDateTime.parse(r.path("period").asText())),r.path("side").asText(),r.path("accountId").asText(),r.path("accountCode").asText(),nativeId(r,"materialId"),optional(r,"materialName"),nativeId(r,"warehouseId"),optional(r,"warehouseName"),decimal(r,"quantity"),decimal(r,"amount"),r.path("currency").asText(),r.path("analytics").isObject()?r.path("analytics").toString():"{}",material,warehouse);
            }
            jdbc.update("update one_c_warehouse_documents set revision=?,state=?,document_date=?,document_number=?,origin=?,correlation_id=?,row_count=?,coverage=?,updated_at=current_timestamp where id=?",revision,n.path("state").asText(),Date.valueOf(n.path("documentDate").asText()),optional(n,"documentNumber"),n.path("origin").asText("ONE_C"),optional(n,"correlationId"),n.path("rows").size(),unmapped?"MAPPING_REQUIRED":"MAPPED_INFORMATION_ONLY",id);
        }
        return Map.of("documentHeadId",id,"revision",revision,"replayed",false,"current",current,"operationalApplication","NOT_APPLIED");
    }
    private Map<String,Object> replay(Map<String,Object> old,String hash){if(!hash.equals(old.get("payload_hash")))throw new ConflictException("Warehouse event/revision identity already has different contents");return Map.of("documentHeadId",old.get("document_head_id"),"revision",old.get("revision"),"replayed",true,"operationalApplication","NOT_APPLIED");}
    private UUID resolve(String kind,String source){
        if(source==null)return null;var ids=jdbc.queryForList("select distinct master_id from warehouse_source_master_links where tenant_id=? and company_id=? and reference_kind=? and (source_id=? or lower(replace(source_id,'-',''))=lower(replace(cast(? as text),'-','')))",UUID.class,tenant(),company(),kind,source,source);return ids.size()==1?ids.getFirst():null;
    }
    private void validate(JsonNode n){
        if(n==null||!n.isObject()||(!n.path("protocolVersion").isIntegralNumber()||n.path("protocolVersion").asInt()!=2)||!n.path("revision").isIntegralNumber()||!n.path("revision").canConvertToLong()||n.path("revision").asLong()<1)throw new BadRequestException("Invalid warehouse v2 revision");
        settings.validate(text(n,"sourceInstanceId",160),text(n,"organizationId",160));uuid(n,"eventId");text(n,"documentType",240);text(n,"documentId",160);
        try{LocalDate.parse(text(n,"documentDate",10));}catch(RuntimeException e){throw new BadRequestException("Invalid documentDate");}
        String state=text(n,"state",16);JsonNode rows=n.path("rows");if(!Set.of("ACTIVE","EMPTY","DELETED").contains(state)||!rows.isArray()||rows.size()>20000||(!state.equals("ACTIVE")&&!rows.isEmpty())||(state.equals("ACTIVE")&&rows.isEmpty()))throw new BadRequestException("Invalid full warehouse snapshot state or rows");
        if(n.has("posted")&&!n.path("posted").isBoolean())throw new BadRequestException("posted must be informational boolean");
        if(n.has("origin"))text(n,"origin",80);if(n.toString().getBytes(StandardCharsets.UTF_8).length>8_000_000)throw new BadRequestException("Warehouse snapshot exceeds size limit");
        Set<String> keys=new HashSet<>();for(JsonNode r:rows){if(!keys.add(text(r,"rowKey",240)))throw new BadRequestException("Duplicate register rowKey");
            if(!Set.of("DT","CT").contains(text(r,"side",2)))throw new BadRequestException("Register side must be DT or CT");
            text(r,"accountId",160);nativeId(r,"materialId");nativeId(r,"warehouseId");text(r,"accountCode",80);text(r,"currency",20);decimal(r,"quantity");decimal(r,"amount");
            try{LocalDateTime.parse(text(r,"period",40));}catch(RuntimeException e){throw new BadRequestException("Invalid row period");}
            if(r.has("analytics")&&!r.path("analytics").isObject())throw new BadRequestException("analytics must be an object");
        }
    }
    private String text(JsonNode n,String field,int max){JsonNode v=n.path(field);if(!v.isTextual()||v.asText().isBlank()||v.asText().length()>max)throw new BadRequestException("Invalid "+field);return v.asText();}
    private String nativeId(JsonNode n,String field){if(!n.hasNonNull(field)||n.path(field).isTextual()&&n.path(field).asText().isBlank())return null;return text(n,field,160);}
    private String optional(JsonNode n,String field){if(!n.hasNonNull(field))return null;if(!n.path(field).isTextual()||n.path(field).asText().length()>1000)throw new BadRequestException("Invalid "+field);return n.path(field).asText();}
    private UUID uuid(JsonNode n,String field){try{return UUID.fromString(text(n,field,36));}catch(RuntimeException e){throw new BadRequestException("Invalid "+field);}}
    private BigDecimal decimal(JsonNode n,String field){String value=text(n,field,80);if(!value.matches("-?[0-9]{1,30}(\\.[0-9]{1,20})?"))throw new BadRequestException("Exact decimal string required for "+field);return new BigDecimal(value);}
    private JsonNode canonical(JsonNode n){if(n.isObject()){var out=mapper.createObjectNode();var keys=new TreeSet<String>();n.fieldNames().forEachRemaining(keys::add);for(String k:keys)out.set(k,canonical(n.get(k)));return out;}if(n.isArray()){var out=mapper.createArrayNode();for(JsonNode v:n)out.add(canonical(v));return out;}return n;}
    private String hash(JsonNode n){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(canonical(n).toString().getBytes(StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException(e);}}

    private static final String HEAD="id,document_type as \"documentType\",document_id as \"documentId\",revision,state,document_date as \"documentDate\",document_number as \"documentNumber\",origin,correlation_id as \"correlationId\",row_count as \"rowCount\",coverage,updated_at as \"updatedAt\"";
    @Transactional(readOnly=true) public List<Map<String,Object>> documents(int limit,int offset){return documents(limit,offset,null,null,null,null);}
    @Transactional(readOnly=true) public List<Map<String,Object>> documents(int limit,int offset,String from,String to,String type,String state){return jdbc.queryForList("select "+HEAD+" from one_c_warehouse_documents where tenant_id=? and company_id=? and (cast(? as text) is null or document_date>=cast(? as date)) and (cast(? as text) is null or document_date<=cast(? as date)) and (cast(? as text) is null or document_type=?) and (cast(? as text) is null or state=?) order by document_date desc,id limit ? offset ?",tenant(),company(),from,from,to,to,type,type,state,state,bound(limit),Math.max(0,offset));}
    @Transactional(readOnly=true) public Map<String,Object> document(UUID id){var heads=jdbc.queryForList("select "+HEAD+" from one_c_warehouse_documents where tenant_id=? and company_id=? and id=?",tenant(),company(),id);if(heads.isEmpty())throw new NotFoundException("Native warehouse document not found");var versions=jdbc.queryForList("select revision,event_id as \"eventId\",state,payload_hash as \"payloadHash\",received_at as \"receivedAt\",payload::text from one_c_warehouse_revisions where document_head_id=? order by revision desc",id);for(var v:versions)v.put("payload",parse(v.get("payload").toString()));return Map.of("document",heads.getFirst(),"versions",versions,"rows",jdbc.queryForList("select row_key as \"rowKey\",period,side,account_id as \"accountId\",account_code as \"accountCode\",material_id as \"materialId\",material_name as \"materialName\",warehouse_id as \"warehouseId\",warehouse_name as \"warehouseName\",quantity::text,amount::text,currency,analytics::text,mapped_material_id as \"mappedMaterialId\",mapped_warehouse_id as \"mappedWarehouseId\" from one_c_warehouse_current_rows where document_head_id=? order by row_key",id));}
    @Transactional(readOnly=true) public List<Map<String,Object>> positions(int limit,int offset){return jdbc.queryForList("select d.source_instance_id as \"sourceInstanceId\",d.organization_id as \"organizationId\",r.account_id as \"accountId\",r.account_code as \"accountCode\",r.material_id as \"materialId\",max(r.material_name) as \"materialName\",r.warehouse_id as \"warehouseId\",max(r.warehouse_name) as \"warehouseName\",r.currency,sum(r.quantity)::text as quantity,sum(r.amount)::text as amount,case when bool_or(r.mapped_material_id is null or r.mapped_warehouse_id is null) then 'MAPPING_REQUIRED' else 'MAPPED_INFORMATION_ONLY' end as coverage from one_c_warehouse_current_rows r join one_c_warehouse_documents d on d.id=r.document_head_id where d.tenant_id=? and d.company_id=? group by d.source_instance_id,d.organization_id,r.account_id,r.account_code,r.material_id,r.warehouse_id,r.currency having sum(r.quantity)<>0 or sum(r.amount)<>0 order by r.material_id,r.warehouse_id,r.account_id,r.currency limit ? offset ?",tenant(),company(),bound(limit),Math.max(0,offset));}
    @Transactional(readOnly=true) public Map<String,Object> coverage(){var out=new LinkedHashMap<String,Object>(settings.config());out.put("documents",count("one_c_warehouse_documents"));out.put("revisions",count("one_c_warehouse_revisions"));out.put("rows",jdbc.queryForObject("select count(*) from one_c_warehouse_current_rows r join one_c_warehouse_documents d on d.id=r.document_head_id where d.tenant_id=? and d.company_id=?",Long.class,tenant(),company()));out.put("unmappedRows",jdbc.queryForObject("select count(*) from one_c_warehouse_current_rows r join one_c_warehouse_documents d on d.id=r.document_head_id where d.tenant_id=? and d.company_id=? and (r.mapped_material_id is null or r.mapped_warehouse_id is null)",Long.class,tenant(),company()));out.put("incompleteHistoryRuns",jdbc.queryForObject("select count(*) from one_c_warehouse_history_runs where tenant_id=? and company_id=? and state<>'COMPLETE'",Long.class,tenant(),company()));out.put("documentTypes",jdbc.queryForList("select document_type as \"documentType\",count(*) as documents from one_c_warehouse_documents where tenant_id=? and company_id=? group by document_type order by document_type",tenant(),company()));out.put("activationReady",false);out.put("blockingReason","INFORMATION_ONLY_NO_OPERATIONAL_FIFO_ADAPTER");return out;}
    private long count(String table){return jdbc.queryForObject("select count(*) from "+table+" where tenant_id=? and company_id=?",Long.class,tenant(),company());}
    private int bound(int n){return Math.max(1,Math.min(200,n));}
    private JsonNode parse(String n){try{return mapper.readTree(n);}catch(Exception e){throw new IllegalStateException(e);}}

    @Transactional public Map<String,Object> createRun(JsonNode n,String key){settings.requireEnabled();lock();if(key==null||key.isBlank()||key.length()>160)throw new BadRequestException("History Idempotency-Key required");LocalDate from,to;try{from=LocalDate.parse(text(n,"from",10));to=LocalDate.parse(text(n,"to",10));}catch(RuntimeException e){throw new BadRequestException("Invalid history dates");}int size=n.path("pageSize").asInt(100);if(to.isBefore(from)||to.isAfter(from.plusDays(366))||size<1||size>200)throw new BadRequestException("History range maximum 366 days; pageSize 1..200");var old=jdbc.queryForList("select id,request_hash from one_c_warehouse_history_runs where tenant_id=? and company_id=? and idempotency_key=?",tenant(),company(),key);if(!old.isEmpty()){if(!hash(n).equals(old.getFirst().get("request_hash")))throw new ConflictException("History key reused with different request");return run((UUID)old.getFirst().get("id"));}UUID id=UUID.randomUUID();jdbc.update("insert into one_c_warehouse_history_runs(id,tenant_id,company_id,source_instance_id,organization_id,date_from,date_to,page_size,idempotency_key,request_hash) values(?,?,?,?,?,?,?,?,?,?)",id,tenant(),company(),settings.source(),settings.organization(),Date.valueOf(from),Date.valueOf(to),size,key,hash(n));return run(id);}
    private static final String RUN="id,date_from as \"from\",date_to as \"to\",state,cursor,snapshot_sequence as \"snapshotSequence\",expected_document_count as \"expectedDocumentCount\",page_size as \"pageSize\",source_instance_id as \"sourceInstanceId\",organization_id as \"organizationId\",page_count as \"pageCount\",document_count as \"documentCount\",row_count as \"rowCount\",created_at as \"createdAt\",completed_at as \"completedAt\",retry_generation as \"retryGeneration\",reported_attempts as \"reportedAttempts\",last_error as \"lastError\",failed_at as \"failedAt\"";
    private Map<String,Object> run(UUID id){var rows=jdbc.queryForList("select "+RUN+" from one_c_warehouse_history_runs where tenant_id=? and company_id=? and id=?",tenant(),company(),id);if(rows.isEmpty())throw new NotFoundException("History run not found");return rows.getFirst();}
    @Transactional(readOnly=true) public List<Map<String,Object>> historyRuns(){return historyRuns(100,0);}
    @Transactional(readOnly=true) public List<Map<String,Object>> historyRuns(int limit,int offset){return jdbc.queryForList("select "+RUN+" from one_c_warehouse_history_runs where tenant_id=? and company_id=? order by created_at desc,id limit ? offset ?",tenant(),company(),bound(limit),Math.max(0,offset));}
    @Transactional(readOnly=true) public Map<String,Object> poll(){settings.requireEnabled();var rows=jdbc.queryForList("select "+RUN+" from one_c_warehouse_history_runs where tenant_id=? and company_id=? and state in('PENDING','LOADING') and source_instance_id=? and organization_id=? order by created_at,id limit 1",tenant(),company(),settings.source(),settings.organization());var out=new LinkedHashMap<String,Object>();out.put("job",rows.isEmpty()?null:new LinkedHashMap<>(rows.getFirst()));if(!rows.isEmpty())((Map<String,Object>)out.get("job")).put("runId",rows.getFirst().get("id"));return out;}
    @Transactional public Map<String,Object> page(JsonNode n){settings.requireEnabled();lock();UUID id=uuid(n,"runId");var r=run(id);settings.validate(String.valueOf(r.get("sourceInstanceId")),String.valueOf(r.get("organizationId")));String page=text(n,"pageId",160),fingerprint=hash(n);var previous=jdbc.queryForList("select payload_hash from one_c_warehouse_history_pages where run_id=? and page_id=?",id,page);if(!previous.isEmpty()){if(!fingerprint.equals(previous.getFirst().get("payload_hash")))throw new ConflictException("History page identity changed");return Map.of("runId",id,"replayed",true,"state",r.get("state"));}
        String cursor=cursor(n,"cursor"),next=cursor(n,"nextCursor");if(n.toString().getBytes(StandardCharsets.UTF_8).length>16_000_000)throw new BadRequestException("History page exceeds size bound");boolean completed=n.path("completed").asBoolean();JsonNode docs=n.path("documents");if(!Set.of("PENDING","LOADING").contains(String.valueOf(r.get("state")))||!cursor.equals(r.get("cursor"))||!n.path("completed").isBoolean()||!n.path("snapshotSequence").isIntegralNumber()||!n.path("snapshotSequence").canConvertToLong()||n.path("snapshotSequence").asLong()<0||!docs.isArray()||docs.size()>((Number)r.get("pageSize")).intValue()||completed&&!next.isEmpty()||!completed&&(next.isEmpty()||next.equals(cursor)))throw new ConflictException("Invalid history page cursor, bounds or completion");long fence=n.path("snapshotSequence").asLong();if(r.get("snapshotSequence")!=null&&fence!=((Number)r.get("snapshotSequence")).longValue())throw new ConflictException("History snapshot fence changed");
        if(!n.path("expectedDocumentCount").isIntegralNumber()||!n.path("expectedDocumentCount").canConvertToLong()||n.path("expectedDocumentCount").asLong()<0)throw new BadRequestException("Expected historical document count required");long expected=n.path("expectedDocumentCount").asLong(),accepted=((Number)r.get("documentCount")).longValue()+docs.size();if(r.get("expectedDocumentCount")!=null&&expected!=((Number)r.get("expectedDocumentCount")).longValue()||accepted>expected||completed&&accepted!=expected)throw new ConflictException("Historical declared count or completion does not reconcile");if(Boolean.TRUE.equals(jdbc.queryForObject("select exists(select 1 from one_c_warehouse_history_pages where run_id=? and (cursor=? or (not ? and cursor=?)))",Boolean.class,id,cursor,completed,next)))throw new ConflictException("Historical cursor was already consumed");Set<String> documents=new HashSet<>();int count=0;for(JsonNode doc:docs){validate(doc);if(Boolean.TRUE.equals(jdbc.queryForObject("select exists(select 1 from one_c_warehouse_history_pages p cross join lateral jsonb_array_elements(p.payload->'documents') d where p.run_id=? and d->>'documentType'=? and d->>'documentId'=?)",Boolean.class,id,doc.path("documentType").asText(),doc.path("documentId").asText())))throw new ConflictException("Historical registrar already accepted in another page");if(!documents.add(doc.path("documentType").asText()+":"+doc.path("documentId").asText()))throw new BadRequestException("A history page must contain each full document once");apply(doc);count+=doc.path("rows").size();}
        jdbc.update("insert into one_c_warehouse_history_pages(run_id,page_id,cursor,next_cursor,payload_hash,document_count,row_count,completed,payload) values(?,?,?,?,?,?,?,?,cast(? as jsonb))",id,page,cursor,next,fingerprint,docs.size(),count,completed,n.toString());jdbc.update("update one_c_warehouse_history_runs set state=?,cursor=?,snapshot_sequence=?,expected_document_count=?,page_count=page_count+1,document_count=document_count+?,row_count=row_count+?,completed_at=case when ? then current_timestamp else null end where id=?",completed?"COMPLETE":"LOADING",next,fence,expected,docs.size(),count,completed,id);return Map.of("runId",id,"replayed",false,"state",completed?"COMPLETE":"LOADING","cursor",next,"documentCount",docs.size(),"rowCount",count);}
    private String cursor(JsonNode n,String field){if(!n.path(field).isTextual()||n.path(field).asText().length()>2000)throw new BadRequestException("Invalid "+field);return n.path(field).asText();}
    @Transactional public Map<String,Object> historyFailure(JsonNode n){
        settings.requireEnabled();lock();UUID id=uuid(n,"runId");var r=run(id);
        settings.validate(String.valueOf(r.get("sourceInstanceId")),String.valueOf(r.get("organizationId")));
        if(!n.path("retryGeneration").isIntegralNumber()||!n.path("retryGeneration").canConvertToLong()||n.path("retryGeneration").asLong()!=((Number)r.get("retryGeneration")).longValue())throw new ConflictException("Historical retry generation changed");
        if(!n.path("attempts").isIntegralNumber()||!n.path("attempts").canConvertToInt()||n.path("attempts").asInt()<1||n.path("attempts").asInt()>10000||!n.path("terminal").isBoolean())throw new BadRequestException("Historical failure attempts and terminal flag required");
        if(!Set.of("PENDING","LOADING","FAILED").contains(String.valueOf(r.get("state"))))throw new ConflictException("Historical run no longer accepts failures");
        int attempts=n.path("attempts").asInt();if(attempts<((Number)r.get("reportedAttempts")).intValue())throw new ConflictException("Historical failure report is stale");
        String error=text(n,"error",4000);boolean terminal=n.path("terminal").asBoolean()||"FAILED".equals(r.get("state"));
        jdbc.update("update one_c_warehouse_history_runs set last_error=?,reported_attempts=?,state=case when ? then 'FAILED' else state end,failed_at=case when ? then coalesce(failed_at,current_timestamp) else failed_at end where id=?",error,attempts,terminal,terminal,id);
        return run(id);
    }
    @Transactional public Map<String,Object> retryRun(UUID id){
        settings.requireEnabled();lock();var r=run(id);settings.validate(String.valueOf(r.get("sourceInstanceId")),String.valueOf(r.get("organizationId")));
        if(!"FAILED".equals(r.get("state")))throw new ConflictException("Only a failed historical run may be retried");
        jdbc.update("update one_c_warehouse_history_runs set state=case when page_count>0 then 'LOADING' else 'PENDING' end,retry_generation=retry_generation+1,reported_attempts=0,last_error=null,failed_at=null where id=?",id);
        return run(id);
    }
    @Transactional public Map<String,Object> cancelRun(UUID id){
        settings.requireEnabled();lock();var r=run(id);settings.validate(String.valueOf(r.get("sourceInstanceId")),String.valueOf(r.get("organizationId")));
        if("CANCELLED".equals(r.get("state")))return r;
        if(!Set.of("PENDING","LOADING","FAILED").contains(String.valueOf(r.get("state"))))throw new ConflictException("Completed historical run cannot be cancelled");
        jdbc.update("update one_c_warehouse_history_runs set state='CANCELLED' where id=?",id);return run(id);
    }
}
